var root=Path.GetFullPath(args[0]);var inventory=new List<object>();
var folders=new[]{"ProcessLens.Core","ProcessLens.Semantics","ProcessLens.Windows","ProcessLens.App","ProcessLens.RamMonitor","ProcessLens.MemoryAgent","ProcessLens.Profiler"};
var files=folders.SelectMany(p=>Directory.GetFiles(Path.Combine(root,p),"*.cs",SearchOption.TopDirectoryOnly)).Where(f=>!f.EndsWith("SysPulseLocalization.cs")).Order().ToArray();
var trees=files.Select(f=>CSharpSyntaxTree.ParseText(File.ReadAllText(f),path:f)).ToArray();
var refs=((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")!).Split(Path.PathSeparator).Select(p=>MetadataReference.CreateFromFile(p));
var globals=CSharpSyntaxTree.ParseText("global using System;global using System.Collections.Generic;global using System.IO;global using System.Linq;global using System.Threading;global using System.Threading.Tasks;");
var comp=CSharpCompilation.Create("Inventory",trees.Append(globals),refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
for(int i=0;i<files.Length;i++) {
 var rewritten=new Localizer(comp.GetSemanticModel(trees[i]),inventory,Path.GetRelativePath(root,files[i])).Visit(trees[i].GetRoot())!;
 string output=rewritten.ToFullString();string name=Path.GetFileName(files[i]);
 if(name=="SelectableText.cs")output=output.Replace("static SelectableText()\n    {","static SelectableText()\n    {\n        TextProperty.OverrideMetadata(typeof(SelectableText),new FrameworkPropertyMetadata(string.Empty,null,LocalizationView.Display));");
 if(name=="Program.cs" && files[i].Contains("ProcessLens.RamMonitor"))output=output.Replace("using ProcessLens.RamMonitor;","using ProcessLens.RamMonitor;\nProcessLens.Core.SysPulseLocalization.InitializeFromArgs(Array.Empty<string>());");
 if(name=="Program.cs" && files[i].Contains("ProcessLens.MemoryAgent"))output=output.Replace("using var mutex =", "SysPulseLocalization.InitializeFromArgs(Array.Empty<string>()); using var mutex =");
 if(name=="Program.cs" && files[i].Contains("ProcessLens.Profiler"))output=output.Replace("return await ProfilerHost.RunAsync(args);", "SysPulseLocalization.InitializeFromArgs(Array.Empty<string>()); return await ProfilerHost.RunAsync(args);");
 if(name=="MainWindow.xaml.cs")output=output.Replace("InitializeComponent();","LocalizationView.Initialize(); InitializeComponent();");
 if(name=="App.xaml.cs")output=output.Replace("SysPulseLocalization.InitializeFromArgs(e.Args);","LocalizationView.Initialize(); SysPulseLocalization.InitializeFromArgs(e.Args);")
  .Replace("base.OnStartup(e);","ShutdownMode=ShutdownMode.OnExplicitShutdown; if(!LocalizationView.SelectAtStartup(e.Args)){Shutdown();return;} base.OnStartup(e);");
 if(name=="ClipboardText.cs")output=output.Replace("Clipboard.SetText(text)","Clipboard.SetText(global::ProcessLens.Core.SysPulseLocalization.Render(text))");
 if(name=="ReportLayout.cs")output=output.Replace("public static IReadOnlyList<Section> Sections(string text)\n    {","public static IReadOnlyList<Section> Sections(string text)\n    {\n        text=global::ProcessLens.Core.SysPulseLocalization.Render(text);");
 if(name=="KnowledgeSignatureEngine.cs") {
  foreach(var field in new[]{"Label","Summary","Meaning","WhyRunning","CloseImpact","CloseRisk","Category"})output=output.Replace("rule."+field+",","global::ProcessLens.Core.SysPulseLocalization.Literal(rule."+field+" ?? string.Empty),");
  output=output.Replace("signal.Evidence ??","(signal.Evidence is null?null:global::ProcessLens.Core.SysPulseLocalization.Literal(signal.Evidence)) ??");
 }
 var dest=Path.Combine(Path.GetDirectoryName(files[i])!,"Localized",Path.GetFileNameWithoutExtension(files[i])+".g.cs");Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.WriteAllText(dest,"// Generated by tools/LocalizationGenerator. Edit the canonical source beside Localized/.\n#nullable enable\n"+output);
}
// Source XAML remains editable and byte-preserved; generated views have explicit exact-key markup.
var keys=new Dictionary<string,string>();var app=Path.Combine(root,"ProcessLens.App");
foreach(var file in Directory.GetFiles(app,"*.xaml").Where(f=>Path.GetFileName(f)!="App.xaml")) {
 string source=File.ReadAllText(file).Replace("xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\"","xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\" xmlns:l10n=\"clr-namespace:ProcessLens.App\"");
 source=Regex.Replace(source,"\\b(Text|Header|Content|ToolTip)=\"([^\"]*)\"",m=>{
  string value=System.Net.WebUtility.HtmlDecode(m.Groups[2].Value);if(string.IsNullOrWhiteSpace(value)||value.StartsWith('{'))return m.Value;
  string key=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)))[..16];keys[key]=value;inventory.Add(new{file=Path.GetRelativePath(root,file),text=value,kind="xaml"});return m.Groups[1].Value+"=\"{l10n:Tr "+key+"}\"";
 });
 foreach(string control in Localizer.ControlNames)source=Regex.Replace(source,@"(</?)"+control+@"(?=[\s/>])",m=>m.Groups[1].Value+"l10n:Localized"+control);
 File.WriteAllText(Path.Combine(app,"Localized",Path.GetFileNameWithoutExtension(file)+".g.xaml"),source);
}
// Knowledge fields are program text, not process-supplied metadata.
foreach(var file in Directory.GetFiles(Path.Combine(root,"ProcessLens.Semantics","knowledge"),"*.json")) {
 using var doc=JsonDocument.Parse(File.ReadAllText(file).TrimStart('\uFEFF'));
 void Walk(JsonElement e,string key="") {if(e.ValueKind==JsonValueKind.Object)foreach(var p in e.EnumerateObject())Walk(p.Value,p.Name);else if(e.ValueKind==JsonValueKind.Array)foreach(var v in e.EnumerateArray())Walk(v);else if(e.ValueKind==JsonValueKind.String && key is "label" or "summary" or "meaning" or "whyRunning" or "closeImpact" or "evidence")inventory.Add(new{file=Path.GetRelativePath(root,file),text=e.GetString(),kind="knowledge"});}
 Walk(doc.RootElement);
}
var options=new JsonSerializerOptions{WriteIndented=true};File.WriteAllText(args[1],JsonSerializer.Serialize(inventory,options));
File.WriteAllText(Path.ChangeExtension(args[1],"xaml.json"),JsonSerializer.Serialize(keys,options));
var projectRoot=Directory.GetParent(root)!.FullName;
var sourceInputs=folders.SelectMany(folder=>Directory.GetFiles(Path.Combine(root,folder),"*.cs",SearchOption.TopDirectoryOnly).Concat(Directory.GetFiles(Path.Combine(root,folder),"*.csproj")))
 .Concat(Directory.GetFiles(app,"*.xaml"))
 .Concat(Directory.GetFiles(Path.Combine(root,"ProcessLens.Core","Localization"),"*",SearchOption.TopDirectoryOnly))
 .Concat(Directory.GetFiles(Path.Combine(app,"Localization"),"*.cs"))
 .Concat(Directory.GetFiles(Path.Combine(root,"ProcessLens.Semantics","knowledge"),"*.json"))
 .Concat(new[]{Path.Combine(projectRoot,"tools","LocalizationGenerator","Program.cs"),Path.Combine(projectRoot,"tools","LocalizationGenerator","LocalizationGenerator.csproj")}).Distinct();
Dictionary<string,string> HashFiles(IEnumerable<string> paths)=>paths.Order().ToDictionary(path=>Path.GetRelativePath(projectRoot,path).Replace('\\','/'),path=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))));
var generated=folders.SelectMany(folder=>Directory.GetFiles(Path.Combine(root,folder,"Localized"),"*",SearchOption.TopDirectoryOnly));
File.WriteAllText(Path.Combine(projectRoot,"localization-manifest.json"),JsonSerializer.Serialize(new{SourceFiles=HashFiles(sourceInputs),GeneratedFiles=HashFiles(generated)},options));
Console.WriteLine($"Generated {files.Length} sources; {inventory.Count} message fragments; {keys.Count} XAML keys.");
class Localizer(SemanticModel model,List<object> inventory,string file):CSharpSyntaxRewriter {
 const string L="global::ProcessLens.Core.SysPulseLocalization.";
 internal static readonly string[] ControlNames=new[]{"TextBlock","Run","Button","CheckBox","ComboBoxItem","Label","MenuItem","Expander","TabItem","GroupBox","TextBox","DataGridTextColumn","DataGridTemplateColumn","DataGridCheckBoxColumn","Window"};
 public override SyntaxNode? VisitClassDeclaration(ClassDeclarationSyntax node) {
  var visited=(ClassDeclarationSyntax)base.VisitClassDeclaration(node)!;
  // x:Class generates another partial declaration whose base is the localized
  // XAML root. Both partial declarations must name the same base type.
  if(file.StartsWith("ProcessLens.App") && file.EndsWith(".xaml.cs") && visited.BaseList is not null) {
   return visited.WithBaseList(visited.BaseList.WithTypes(SyntaxFactory.SeparatedList(
    visited.BaseList.Types.Select(t=>ControlNames.Contains(t.Type.ToString().Split('.').Last())
     ? t.WithType(SyntaxFactory.ParseTypeName("global::ProcessLens.App.Localized"+t.Type.ToString().Split('.').Last())).WithTriviaFrom(t)
     : t))));
  }
  return visited;
 }
 ExpressionSyntax Call(string name,string args)=>SyntaxFactory.ParseExpression(L+name+"("+args+")");
 bool IsRaw(SyntaxNode node)=>node is not InterpolatedStringExpressionSyntax && node is not BinaryExpressionSyntax && Regex.IsMatch(node.ToString(),@"(?i)\b(?:Name|DisplayName|ExecutablePath|CommandLine|ProjectRoot|ProductName|CompanyName|FileDescription|PackageFullName|ApplicationUserModelId|WindowTitles|ServiceDisplayNames|ServiceNames|ModuleNames|Ssid|Bssid|Mac|SourceAddress|DestinationAddress|InterfaceName|Application|Path|FileName|script|host)\b");
 public override SyntaxNode? VisitObjectCreationExpression(ObjectCreationExpressionSyntax node) {
  var visited=(ObjectCreationExpressionSyntax)base.VisitObjectCreationExpression(node)!;
  string name=node.Type.ToString().Split('.').Last();
  if(file.StartsWith("ProcessLens.App") && ControlNames.Contains(name))return visited.WithType(SyntaxFactory.ParseTypeName("global::ProcessLens.App.Localized"+name));
  return visited;
 }
 public override SyntaxNode? VisitImplicitObjectCreationExpression(ImplicitObjectCreationExpressionSyntax node) {
  var visited=(ImplicitObjectCreationExpressionSyntax)base.VisitImplicitObjectCreationExpression(node)!;string? name=model.GetTypeInfo(node).Type?.Name;
  if(file.StartsWith("ProcessLens.App") && name is not null && ControlNames.Contains(name))return SyntaxFactory.ObjectCreationExpression(SyntaxFactory.ParseTypeName("global::ProcessLens.App.Localized"+name)).WithArgumentList(visited.ArgumentList).WithInitializer(visited.Initializer).WithTriviaFrom(node);
  return visited;
 }
 public override SyntaxNode? VisitInterpolatedStringExpression(InterpolatedStringExpressionSyntax node) {
  foreach(var t in node.Contents.OfType<InterpolatedStringTextSyntax>())inventory.Add(new{file,text=t.TextToken.ValueText,kind="fragment"});
  var visited=(InterpolatedStringExpressionSyntax)base.VisitInterpolatedStringExpression(node)!;
  var parts=visited.Contents.Select((p,i)=>p is InterpolationSyntax h?h.WithExpression(SyntaxFactory.ParenthesizedExpression(IsRaw(((InterpolationSyntax)node.Contents[i]).Expression)?Call("Opaque",h.Expression.ToString()):h.Expression)):p);
  return Call("Capture",visited.WithContents(SyntaxFactory.List(parts)).ToString()).WithTriviaFrom(node);
 }
 public override SyntaxNode? VisitLiteralExpression(LiteralExpressionSyntax node) {
  if(!node.IsKind(SyntaxKind.StringLiteralExpression))return base.VisitLiteralExpression(node);
  string text=node.Token.ValueText;inventory.Add(new{file,text,kind="literal"});
  if(text.Length==0||node.Ancestors().Any(n=>n is AttributeSyntax or ConstantPatternSyntax or CaseSwitchLabelSyntax or ParameterSyntax||n is FieldDeclarationSyntax f&&f.Modifiers.Any(SyntaxKind.ConstKeyword)||n is LocalDeclarationStatementSyntax d&&d.Modifiers.Any(SyntaxKind.ConstKeyword)))return node;
  return Call("Literal",node.WithoutTrivia().ToString()).WithTriviaFrom(node);
 }
 public override SyntaxNode? VisitBinaryExpression(BinaryExpressionSyntax node) {
  var visited=(BinaryExpressionSyntax)base.VisitBinaryExpression(node)!;
  if(node.IsKind(SyntaxKind.AddExpression)&&model.GetTypeInfo(node).Type?.SpecialType==SpecialType.System_String) {
   if(node.Ancestors().Any(n=>n is AttributeSyntax||n is FieldDeclarationSyntax f&&f.Modifiers.Any(SyntaxKind.ConstKeyword)||n is LocalDeclarationStatementSyntax d&&d.Modifiers.Any(SyntaxKind.ConstKeyword)))return node;
   string Protect(ExpressionSyntax a,ExpressionSyntax b)=>IsRaw(a)?L+"Opaque("+b.WithoutTrivia()+")":b.WithoutTrivia().ToString();
   return Call("Concat",Protect(node.Left,visited.Left)+","+Protect(node.Right,visited.Right)).WithTriviaFrom(node);
  }return visited;
 }
 public override SyntaxNode? VisitAssignmentExpression(AssignmentExpressionSyntax node) {
  var visited=(AssignmentExpressionSyntax)base.VisitAssignmentExpression(node)!;
  string property=node.Left is MemberAccessExpressionSyntax access?access.Name.Identifier.ValueText:node.Left is IdentifierNameSyntax identifier?identifier.Identifier.ValueText:"";
  string? target=node.Left is MemberAccessExpressionSyntax member?model.GetTypeInfo(member.Expression).Type?.Name:null;
  if(node.Parent is InitializerExpressionSyntax initializer && initializer.Parent is ObjectCreationExpressionSyntax creation)target=creation.Type.ToString().Split('.').Last();
  bool nativeDialog=target is "OpenFileDialog" or "SaveFileDialog";
  bool ownWindow=file.EndsWith("NewTaskWindow.cs") || file.EndsWith("ServiceDetailsWindow.cs");
  if(file.StartsWith("ProcessLens.App") && ((nativeDialog && property is "Title" or "Filter") || (ownWindow && property=="Title")))return visited.WithRight(Call("Render",visited.Right.ToString()));
  if(file.StartsWith("ProcessLens.MemoryAgent") && (node.Left is MemberAccessExpressionSyntax m&&m.Name.Identifier.ValueText=="Text" || node.Left is IdentifierNameSyntax id&&id.Identifier.ValueText=="Text"))return visited.WithRight(Call("Render",visited.Right.ToString()));
  return visited;
 }
 public override SyntaxNode? VisitInvocationExpression(InvocationExpressionSyntax node) {
  if(node.Expression.ToString() is "string.Create" or "FormattableString.Invariant")return node;
  var v=(InvocationExpressionSyntax)base.VisitInvocationExpression(node)!;var sym=model.GetSymbolInfo(node).Symbol as IMethodSymbol;
  if(node.Expression is MemberAccessExpressionSyntax o && v.Expression is MemberAccessExpressionSyntax m) {
   string type=sym?.ContainingType?.ToString()??"",name=o.Name.Identifier.ValueText;
   if(type=="System.Text.StringBuilder") {
    if(name is "Append" or "AppendLine" && node.ArgumentList.Arguments.Count<=1)return Call(name,m.Expression.WithoutTrivia()+(v.ArgumentList.Arguments.Count==0?"":","+v.ArgumentList.Arguments[0])).WithTriviaFrom(node);
    if(name=="ToString"&&node.ArgumentList.Arguments.Count==0)return Call("BuilderText",m.Expression.WithoutTrivia().ToString()).WithTriviaFrom(node);
   }
   if(type is "string" or "System.String") {
    if(name=="Join"&&node.ArgumentList.Arguments.Count==2 && model.GetTypeInfo(node.ArgumentList.Arguments[1].Expression).Type?.SpecialType!=SpecialType.System_String)return Call("Join",string.Join(",",v.ArgumentList.Arguments)).WithTriviaFrom(node);
    if(name is "Trim" or "TrimStart" or "TrimEnd" or "ToUpperInvariant" or "ToLowerInvariant" && node.ArgumentList.Arguments.Count==0)return Call("Map",m.Expression.WithoutTrivia()+",__s=>__s."+name+"()").WithTriviaFrom(node);
   }
   if(file.StartsWith("ProcessLens.MemoryAgent") && name=="ShowBalloonTip")return v.WithArgumentList(v.ArgumentList.WithArguments(SyntaxFactory.SeparatedList(v.ArgumentList.Arguments.Select((a,i)=>i is 1 or 2?a.WithExpression(Call("Render",a.Expression.ToString())):a))));
   if((o.Expression.ToString() is "Console" or "Console.Error" && name is "Write" or "WriteLine") || (type=="System.IO.File" && name is "AppendAllText" or "WriteAllText")) {
    int index=type=="System.IO.File"?1:0;
    if(v.ArgumentList.Arguments.Count>index && model.GetTypeInfo(node.ArgumentList.Arguments[index].Expression).Type?.SpecialType==SpecialType.System_String) {
      var arg=v.ArgumentList.Arguments[index];return v.WithArgumentList(v.ArgumentList.WithArguments(v.ArgumentList.Arguments.Replace(arg,arg.WithExpression(Call("Render",arg.Expression.ToString())))));
    }
   }
   if(o.Expression.ToString()=="MessageBox" && name=="Show")return v.WithArgumentList(v.ArgumentList.WithArguments(SyntaxFactory.SeparatedList(v.ArgumentList.Arguments.Select((a,i)=>model.GetTypeInfo(node.ArgumentList.Arguments[i].Expression).Type?.SpecialType==SpecialType.System_String?a.WithExpression(Call("Render",a.Expression.ToString())):a))));
  }
  if(node.Expression is IdentifierNameSyntax clean && clean.Identifier.ValueText=="Clean" && node.ArgumentList.Arguments.Count==1 && model.GetTypeInfo(node).Type?.SpecialType==SpecialType.System_String)return Call("Map",v.ArgumentList.Arguments[0].Expression+",__s=>Clean(__s)").WithTriviaFrom(node);
  return v;
 }
}
